 # Parse issue date\n        parts = issue_date.split('/')\n        if len(parts) < 2:\n            continue\n            \n        month = int(parts[0])\n        \n        # Filter: Feb-Apr (2-4) and amount > 2400\n        if month >= 2 and month <= 4 and amount > 2400:\n            values.append(amount)\n            print(f\"  {issue_date}: ${amount} - EXCEEDS\")\n    \n    return values\n\n# Read files\nwith open('/app/resources/treasury_bulletin_1972_05_page_89.txt', 'r') as f:\n    text_1972 = f.read()\n    \nwith open('/app/resources/treasury_bulletin_1973_05_page_95.txt', 'r') as f:\n    text_1973 = f.read()\n    \nwith open('/app/resources/treasury_bulletin_1974_05_page_83.txt', 'r') as f:\n    text_1974 = f.read()\n\nprint(\"1972:\")\nvalues_1972 = parse_year(text_1972, 1972)\nprint(f\"\\n1972 count: {len(values_1972)}, values: {values_1972}\")\n\nprint(\"\\n1973:\")\nvalues_1973 = parse_year(text_1973, 1973)\nprint(f\"\\n1973 count: {len(values_1973)}, values: {values_1973}\")\n\nprint(\"\\n1974:\")\nvalues_1974 = parse_year(text_1974, 1974)\nprint(f\"\\n1974 count: {len(values_1974)}, values: {values_1974}\")\n\n# Calculate totals\ntotal = len(values_1972) + len(values_1973) + len(values_1974)\nprint(f\"\\n=== TOTAL COUNT: {total} ===\")\n\n# Calculate geometric mean\nall_values = values_1972 + values_1973 + values_1974\nproduct = 1\nfor v in all_values:\n    product *= v\n    \nn = len(all_values)\ngm = product ** (1/n)\nprint(f\"\\n=== GEOMETRIC MEAN: {gm:.2f} ===\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
